CREATE PROCEDURE logging.SP_DeleteCryptoDataForRefresh
    @trading_pair VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN

        DELETE FROM gold.crypto_candles_reporting
        WHERE [Trading Pair] = @trading_pair;

        DELETE FROM silver.crypto_candles
        WHERE trading_pair = @trading_pair;

    END 
END;
GO
